def max_beauty(n, k, s):
    max_length = 0
    for char in ['a', 'b']:
        left = 0
        changes = 0
        for right in range(n):
            if s[right] != char:
                changes += 1
            while changes > k:
                if s[left] != char:
                    changes -= 1
                left += 1
            max_length = max(max_length, right - left + 1)
    return max_length

# Read input
n, k = map(int, input().split())
s = input()

# Output the result
print(max_beauty(n, k, s))
